const LAMINAS={"breakout_strategy": "data:image/jpeg;base64,", "high_prob": "data:image/jpeg;base64,", "ms_flow": "data:image/jpeg;base64,", "bullish_retest": "data:image/jpeg;base64,", "liquidity_trap": "data:image/jpeg;base64,", "trend_reversal": "data:image/jpeg;base64,", "ms_setup": "data:image/jpeg;base64,"};
const I18N={"es": {"titulo": "MAGMAX Scanner", "sub": "Identifica la situación y te da lo que se midió, no lo que se promete", "cabCaptura": "1 · Captura (opcional)", "cabSit": "2 · Qué dice MAGMAX", "cabLect": "3 · Lectura", "cabBit": "Bitácora", "p1": "Estructura", "p2": "Último evento", "subeFoto": "Ctrl+V para pegar la captura", "subeFoto2": "O toca aquí para elegir un archivo. Se queda en tu equipo.", "fotoOk": "Captura lista", "guardar": "Guardar en bitácora", "otra": "Otra lectura", "limpiar": "Borrar bitácora", "salio": "Salió", "nosalio": "No salió", "bitVacia": "Sin registros todavía. Guarda una lectura para empezar.", "bitSinMarcar": "{n} registros. Marca cómo salieron para medir tu lectura.", "bitResumen": "{n} registros · {m} marcados · acertaste {p}%", "confirmar": "¿Borrar toda la bitácora? No se puede deshacer.", "pie": "Los porcentajes salen del backtest de tu propio MNQ (1,128 eventos de estructura, 947 retests, jun-2025 a ago-2026). No son predicciones: son frecuencias pasadas. Esta app no da señales de entrada.", "op1": [{"v": "alcista", "t": "ALCISTA (HH+HL)", "d": "máximos y mínimos subiendo"}, {"v": "bajista", "t": "BAJISTA (LH+LL)", "d": "máximos y mínimos bajando"}, {"v": "rango", "t": "RANGO / TRANSICIÓN", "d": "el panel dice MIXTO"}], "op2": [{"v": "bos", "t": "BOS — rompió a favor", "d": "continuación de la estructura"}, {"v": "choch", "t": "CHoCH — rompió en contra", "d": "primera ruptura contraria"}, {"v": "retest", "t": "RETEST DADO", "d": "el precio volvió al nivel roto"}, {"v": "sweep", "t": "SWEEP", "d": "mecha barrió el swing y cerró de regreso"}, {"v": "nada", "t": "Nada — precio en medio", "d": "sin evento reciente"}], "lect": {"bosAlc": {"cls": "duda", "vered": "Contexto a favor", "setup": "Breakout and retest (alcista)", "img": "breakout_strategy", "lee": "Rompió estructura al alza dentro de una tendencia alcista. La lámina dice que la entrada NO es la ruptura: es el regreso al nivel. Tus datos coinciden en que el regreso casi siempre llega.", "nums": [["84%", "el retest llega", "bien"], ["62%", "el siguiente evento sigue ↑", "neu"], ["79%", "del retest toca stop", "mal"], ["−0.41R", "retest solo, esperanza", "mal"]], "aviso": "<b>Cuidado con la trampa.</b> Que el precio vuelva al nivel (84%) no significa que rebote: entrar solo por estar en el nivel pierde −0.41R en 947 casos medidos. El nivel es el lugar, no la señal. Espera que MomentumVolumen apile régimen + fuerza + volumen + gatillo."}, "bosBaj": {"cls": "duda", "vered": "Contexto a favor", "setup": "Breakout and retest (bajista)", "img": "breakout_strategy", "lee": "Rompió estructura a la baja dentro de una tendencia bajista. Mismo esquema que la lámina, en espejo: la entrada es el regreso al nivel roto, no la ruptura.", "nums": [["84%", "el retest llega", "bien"], ["59%", "el siguiente evento sigue ↓", "neu"], ["79%", "del retest toca stop", "mal"], ["−0.41R", "retest solo, esperanza", "mal"]], "aviso": "<b>Cuidado con la trampa.</b> El regreso al nivel es casi seguro; el rebote no. Entrar solo por el nivel pierde −0.41R medido. Deja que el embudo confirme antes de tocar el ratón."}, "chochBaj": {"cls": "duda", "vered": "Posible giro", "setup": "Break of structure / trend reversal", "img": "trend_reversal", "lee": "Venías alcista y el precio rompió el último mínimo: primera ruptura en contra. La lámina la llama market structure break. No es reversión confirmada todavía — se confirma con un BOS bajista después.", "nums": [["67%", "confirma con BOS ↓", "neu"], ["n=15", "muestra chica", "mal"], ["84%", "el retest llega", "bien"]], "aviso": "<b>Este número es débil.</b> Solo 15 casos en 7 meses; con esa muestra el 67% puede ser 45% o 85%. Trátalo como aviso de que la estructura cambió, no como probabilidad. Y ojo: tras un CHoCH la estructura queda en transición — el régimen se enfría y el embudo casi no dispara ahí."}, "chochAlc": {"cls": "duda", "vered": "Posible giro", "setup": "Break of structure / trend reversal", "img": "trend_reversal", "lee": "Venías bajista y el precio rompió el último máximo. Primera ruptura en contra: la estructura queda en transición hasta que un BOS alcista la confirme.", "nums": [["89%", "confirma con BOS ↑", "neu"], ["n=19", "muestra chica", "mal"], ["84%", "el retest llega", "bien"]], "aviso": "<b>Ese 89% miente por muestra.</b> Son 19 casos en 7 meses. Úsalo para saber que la estructura cambió, no para dimensionar riesgo. El número serio llega cuando el año completo junte ~60 casos."}, "retestAlc": {"cls": "no", "vered": "Aquí NO se entra solo", "setup": "Bullish retest / demand zone", "img": "bullish_retest", "lee": "El precio volvió al nivel roto, que es exactamente lo que la lámina marca como LONG ENTRY. Aquí está el hallazgo más incómodo de tu propio backtest.", "nums": [["19%", "llega a 2R", "mal"], ["79%", "toca el stop antes", "mal"], ["−0.41R", "esperanza del retest solo", "mal"], ["+0.51R", "con el embudo completo", "bien"]], "aviso": "<b>Medido en 947 retests: entrar aquí pierde dinero.</b> Y el volumen no ayuda — probamos RVOL alto contra bajo y las cuatro franjas dan lo mismo (−0.35R a −0.48R). La diferencia entre −0.41R y +0.51R es todo lo que el embudo exige además del nivel: régimen de tendencia, cuerpo ≥0.6, RVOL ≥1.5 en la señal, gatillo a 0.5×ATR y filtro de espacio. La zona es el lugar correcto; el filtro es el producto."}, "retestBaj": {"cls": "no", "vered": "Aquí NO se entra solo", "setup": "Bearish retest / supply zone", "img": "high_prob", "lee": "El precio regresó al nivel roto por abajo. La lámina lo marca como entrada corta. Tus datos dicen otra cosa.", "nums": [["19%", "llega a 2R", "mal"], ["79%", "toca el stop antes", "mal"], ["−0.41R", "esperanza del retest solo", "mal"], ["+0.51R", "con el embudo completo", "bien"]], "aviso": "<b>Medido en 947 retests: entrar aquí pierde dinero.</b> El volumen en el retest tampoco separa (probado, n=947). Espera el apilamiento completo del embudo. Sin esos filtros, esta zona es una máquina de comisiones."}, "sweep": {"cls": "duda", "vered": "Trampa de liquidez", "setup": "Liquidity sweep / false breakout", "img": "liquidity_trap", "lee": "Una mecha perforó el swing y el cierre regresó: barrieron stops sin aceptación de precio. La lámina lo llama liquidity sweep y anticipa reversión.", "nums": [["69%", "revierte ≥1 ATR", "bien"], ["≤30", "velas de ventana", "neu"], ["~13", "sweeps por día", "mal"], ["70/67/67", "en las 3 ventanas", "bien"]], "aviso": "<b>El 69% es sólido y estable</b> — casi idéntico en los tres trimestres. Pero ocurren ~13 al día: son demasiado frecuentes para operarlos sueltos, y por eso su alerta viene apagada. Úsalo como contexto: un sweep en contra de tu idea es motivo para esperar, no para entrar al revés."}, "rango": {"cls": "no", "vered": "Fuera del mercado", "setup": "Rango / transición", "img": "ms_flow", "lee": "Sin cadena clara de HH+HL ni LH+LL. Es la fase de acumulación o distribución de la lámina, y es donde tu sistema deja de tener ventaja.", "nums": [["0.37", "PF del lateral", "mal"], ["1.84", "PF en tendencia", "bien"], ["~5.5", "eventos por día", "neu"]], "aviso": "<b>El régimen lateral midió PF 0.37 en tu backtest.</b> Por eso MomentumVolumen sale con SoloEnTendencia activo y no dispara aquí. El silencio del indicador en rango no es una falla: es de dónde sale el PF 1.84. Esperar también es operar."}, "nada": {"cls": "duda", "vered": "Sin evento", "setup": "Precio entre niveles", "img": "ms_setup", "lee": "No hay ruptura reciente ni retest activo. El precio navega entre niveles y no hay nada que la estructura pueda decirte todavía.", "nums": [["~5.5", "eventos por día (15m)", "neu"], ["1.5h", "promedio entre eventos", "neu"]], "aviso": "Con estructura de 15m el promedio es un evento cada hora y media. Horas sin nada son normales. Deja que MAGMAX te avise con sonido y parpadeo en vez de vigilar la pantalla."}}, "btnPegar": "Pegar del portapapeles", "pegado": "Captura pegada.", "noImagen": "Eso no es una imagen.", "nadaPortapapeles": "No hay ninguna imagen en el portapapeles.", "permiso": "El navegador no dio permiso. Usa Ctrl+V o elige el archivo.", "sinApi": "Este navegador no permite leer el portapapeles. Usa Ctrl+V."}, "en": {"titulo": "MAGMAX Scanner", "sub": "Identify the situation and get what was measured, not what's promised", "cabCaptura": "1 · Screenshot (optional)", "cabSit": "2 · What MAGMAX says", "cabLect": "3 · Reading", "cabBit": "Journal", "p1": "Structure", "p2": "Last event", "subeFoto": "Ctrl+V to paste the screenshot", "subeFoto2": "Or tap to pick a file. It stays on your device.", "fotoOk": "Screenshot ready", "guardar": "Save to journal", "otra": "New reading", "limpiar": "Clear journal", "salio": "Worked", "nosalio": "Didn't", "bitVacia": "No entries yet. Save a reading to start.", "bitSinMarcar": "{n} entries. Mark how they went to measure your reading.", "bitResumen": "{n} entries · {m} marked · you were right {p}%", "confirmar": "Clear the whole journal? This can't be undone.", "pie": "Percentages come from the backtest of your own MNQ (1,128 structure events, 947 retests, Jun-2025 to Aug-2026). They're not predictions: they're past frequencies. This app gives no entry signals.", "op1": [{"v": "alcista", "t": "BULLISH (HH+HL)", "d": "highs and lows rising"}, {"v": "bajista", "t": "BEARISH (LH+LL)", "d": "highs and lows falling"}, {"v": "rango", "t": "RANGE / TRANSITION", "d": "panel says MIXED"}], "op2": [{"v": "bos", "t": "BOS — broke with trend", "d": "structure continuation"}, {"v": "choch", "t": "CHoCH — broke against", "d": "first counter break"}, {"v": "retest", "t": "RETEST HAPPENED", "d": "price returned to the broken level"}, {"v": "sweep", "t": "SWEEP", "d": "wick took the swing, close came back"}, {"v": "nada", "t": "Nothing — price mid-range", "d": "no recent event"}], "lect": {"bosAlc": {"cls": "duda", "vered": "Context in favor", "setup": "Breakout and retest (bullish)", "img": "breakout_strategy", "lee": "Structure broke upward inside an uptrend. The sheet says the entry is NOT the break: it's the return to the level. Your data agrees the return almost always comes.", "nums": [["84%", "retest arrives", "bien"], ["62%", "next event continues ↑", "neu"], ["79%", "of retests hit stop", "mal"], ["−0.41R", "retest alone, expectancy", "mal"]], "aviso": "<b>Mind the trap.</b> Price returning to the level (84%) doesn't mean it bounces: entering just for being at the level loses −0.41R across 947 measured cases. The level is the place, not the signal. Wait for MomentumVolumen to stack regime + body + volume + trigger."}, "bosBaj": {"cls": "duda", "vered": "Context in favor", "setup": "Breakout and retest (bearish)", "img": "breakout_strategy", "lee": "Structure broke down inside a downtrend. Same scheme as the sheet, mirrored: the entry is the return to the broken level, not the break.", "nums": [["84%", "retest arrives", "bien"], ["59%", "next event continues ↓", "neu"], ["79%", "of retests hit stop", "mal"], ["−0.41R", "retest alone, expectancy", "mal"]], "aviso": "<b>Mind the trap.</b> The return is near certain; the bounce isn't. Entering on the level alone loses −0.41R measured. Let the funnel confirm before you touch the mouse."}, "chochBaj": {"cls": "duda", "vered": "Possible turn", "setup": "Break of structure / trend reversal", "img": "trend_reversal", "lee": "You were bullish and price broke the last low: first counter break. The sheet calls it a market structure break. Not a confirmed reversal yet — a bearish BOS confirms it.", "nums": [["67%", "confirms with BOS ↓", "neu"], ["n=15", "small sample", "mal"], ["84%", "retest arrives", "bien"]], "aviso": "<b>This number is weak.</b> Only 15 cases in 7 months; with that sample 67% could be 45% or 85%. Treat it as notice that structure changed, not as a probability. Also: after a CHoCH structure sits in transition — regime cools and the funnel barely fires there."}, "chochAlc": {"cls": "duda", "vered": "Possible turn", "setup": "Break of structure / trend reversal", "img": "trend_reversal", "lee": "You were bearish and price broke the last high. First counter break: structure stays in transition until a bullish BOS confirms it.", "nums": [["89%", "confirms with BOS ↑", "neu"], ["n=19", "small sample", "mal"], ["84%", "retest arrives", "bien"]], "aviso": "<b>That 89% lies through sample size.</b> It's 19 cases in 7 months. Use it to know structure changed, not to size risk. The serious number arrives when a full year gathers ~60 cases."}, "retestAlc": {"cls": "no", "vered": "Don't enter on this alone", "setup": "Bullish retest / demand zone", "img": "bullish_retest", "lee": "Price returned to the broken level — exactly what the sheet marks as LONG ENTRY. This is where your own backtest gets uncomfortable.", "nums": [["19%", "reaches 2R", "mal"], ["79%", "hits stop first", "mal"], ["−0.41R", "retest alone", "mal"], ["+0.51R", "with the full funnel", "bien"]], "aviso": "<b>Measured across 947 retests: entering here loses money.</b> And volume doesn't help — we tested high vs low RVOL and all four bands come out the same (−0.35R to −0.48R). The gap between −0.41R and +0.51R is everything the funnel demands beyond the level: trend regime, body ≥0.6, RVOL ≥1.5 on the signal, trigger at 0.5×ATR and the space filter. The zone is the right place; the filter is the product."}, "retestBaj": {"cls": "no", "vered": "Don't enter on this alone", "setup": "Bearish retest / supply zone", "img": "high_prob", "lee": "Price came back to the broken level from below. The sheet marks it as a short entry. Your data says otherwise.", "nums": [["19%", "reaches 2R", "mal"], ["79%", "hits stop first", "mal"], ["−0.41R", "retest alone", "mal"], ["+0.51R", "with the full funnel", "bien"]], "aviso": "<b>Measured across 947 retests: entering here loses money.</b> Volume at the retest doesn't separate either (tested, n=947). Wait for the funnel's full stack. Without those filters this zone is a commission machine."}, "sweep": {"cls": "duda", "vered": "Liquidity trap", "setup": "Liquidity sweep / false breakout", "img": "liquidity_trap", "lee": "A wick pierced the swing and the close came back: stops taken without price acceptance. The sheet calls it a liquidity sweep and expects reversal.", "nums": [["69%", "reverses ≥1 ATR", "bien"], ["≤30", "bar window", "neu"], ["~13", "sweeps per day", "mal"], ["70/67/67", "across 3 windows", "bien"]], "aviso": "<b>That 69% is solid and stable</b> — nearly identical across three quarters. But they happen ~13 times a day: far too frequent to trade alone, which is why their alert ships off. Use it as context: a sweep against your idea is a reason to wait, not to flip."}, "rango": {"cls": "no", "vered": "Stay out", "setup": "Range / transition", "img": "ms_flow", "lee": "No clear HH+HL or LH+LL chain. This is the sheet's accumulation or distribution phase, and it's where your system loses its edge.", "nums": [["0.37", "range PF", "mal"], ["1.84", "trend PF", "bien"], ["~5.5", "events per day", "neu"]], "aviso": "<b>The range regime measured PF 0.37 in your backtest.</b> That's why MomentumVolumen ships with trend-only on and won't fire here. The indicator's silence in a range isn't a failure: it's where the 1.84 comes from. Waiting is also trading."}, "nada": {"cls": "duda", "vered": "No event", "setup": "Price between levels", "img": "ms_setup", "lee": "No recent break and no active retest. Price is drifting between levels and structure has nothing to tell you yet.", "nums": [["~5.5", "events per day (15m)", "neu"], ["1.5h", "average between events", "neu"]], "aviso": "With 15m structure the average is one event every hour and a half. Hours of nothing are normal. Let MAGMAX call you with sound and blink instead of watching the screen."}}, "btnPegar": "Paste from clipboard", "pegado": "Screenshot pasted.", "noImagen": "That isn't an image.", "nadaPortapapeles": "No image in the clipboard.", "permiso": "The browser denied permission. Use Ctrl+V or pick the file.", "sinApi": "This browser can't read the clipboard. Use Ctrl+V."}};
